ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["scenes_any_23"] = {
{"s5_c01_zip_tied_medic_034","any",2,"reg=military|day=1,20|mood=grim",{1,"MPs flex-cuffed a civilian to the post by the processing tent - said he bit a medic",2,"Bit him? Or bit him bit him?",1,"That's what everybody's waiting to find out",2,"How long's that take?",1,"Doc says by supper, the medic's sitting over by the water buffalo, not talking to anybody"}},
{"s5_c01_phone_number_035","any",2,"reg=military|day=3,40|hour=5,10|mood=sad",{1,"Somebody spray-painted the barriers again overnight",2,"What's it say this time?",1,"Just a phone number - Louisville area code - nothing else",2,"Phones don't work, man, nothing out there rings",1,"I know it, I memorized it anyhow"}},
{"s5_c01_warm_pop_036","any",3,"reg=military|day=1,15|hour=11,18|mood=warm|world=vehicle,road",{1,"Old fella in the car line went down in the heat - right on the asphalt next to his Oldsmobile",2,"Anybody get to him?",3,"Other civilians did, poured their own drinking water on his neck and fanned him with a road map",1,"Doc was hollering instructions over the barrier the whole time",2,"He get up?",1,"Sat up, drank somebody's warm pop - then he waved at Doc like they were old friends"}},
{"s5_c01_trestle_037","any",3,"reg=military|day=3,40|mood=calm",{1,"Engineers want to drop the old railroad trestle over Otter Creek",2,"Why? Nobody's driving over a trestle",3,"Because they walk over it, single file, all night long, like they're filing into church",1,"Railroad's gonna be sore about it",2,"Railroad's welcome to file a complaint, through the wire"}},
{"s5_c01_church_lot_game_038","any",2,"reg=military|day=3,30|mood=sad",{1,"Kids in the church lot past the barrier have a new game - half are soldiers, half are sick ones",2,"Who wins?",1,"Nobody, soldiers keep telling the sick ones to go home, and the sick ones keep coming back"}},
{"s5_c01_hands_on_wire_039","any",3,"reg=military|tmp=seasoned,veteran|day=2,20|hour=17,23|mood=grim",{1,"New guidance came down at {time}, anybody who puts hands on the wire after dark is to be treated as a threat",2,"Anybody?",1,"That's the word they used",3,"What if it's a kid?",1,"Then you get your light on that kid before the kid gets to the wire - that's all the room they left us"}},
{"s5_c01_yellow_tacks_040","any",2,"reg=military|day=5,45|mood=grim",{1,"Major's map in the command post has red pins everywhere the line's been breached",2,"How many pins?",1,"They ran out of red pins Wednesday, it's yellow thumbtacks now",2,"Yellow's a cheerier color, at least"}},
{"s5_c01_fort_knocks_041","any",3,"reg=military|day=3,25|mood=funny",{1,"Third fake pass today, somebody in Muldraugh's got a typewriter and a rubber stamp",2,"Any of them good?",3,"This one says Department of the Army, Fort Knocks - K-N-O-C-K-S",1,"Close, though - real close"}},
{"s5_c01_nurse_wants_in_042","any",3,"reg=military|day=2,20|hour=4,11|mood=warm",{1,"Lady walked up from the outside this morning - wanted in, said she's an ER nurse and they must need nurses in there",2,"We let her?",1,"Nobody in, nobody out, she argued with the captain the better part of an hour",3,"What'd she do after?",1,"Left a sack of gauze and tape against the barrier - wrote on it in marker - for inside"}},
{"s5_c01_idling_humvee_043","any",2,"reg=military|tmp=seasoned,veteran|hour=19,5|mood=angry|world=vehicle",{1,"Shut that engine off",2,"Radio's eating the battery, Sergeant, I'm charging it",1,"You're calling them in, two already came up out of the corn to see who's idling",2,"Shutting it off"}},
{"s5_c01_drive_in_044","any",2,"reg=military|hour=22,6|mood=calm|world=road",{1,"Relieving you - what've you got?",2,"Headlights up on the ridge road around midnight, stopped and sat there an hour, then they backed off",1,"Anybody get out?",2,"Nobody, just sat up there looking at our lights, like a drive-in movie"}},
{"s5_c01_history_books_045","any",3,"reg=military|day=2,40|mood=funny",{1,"Lieutenant says what we're doing out here is going in the history books",2,"Which chapter?",3,"The one the teacher skips"}},
{"s5_c01_nine_letters_046","any",1,"reg=military|role=soldier_nco|tmp=seasoned,veteran|day=6,90|hour=20,3|mood=sad",{1,"Nine letters, nine letters to write, and no mail",1,"Writing 'em anyway - proper, name, rank, what kind of man he was",1,"Spec Four Dunbar, cheated at cards and everybody knew, can't put that in, I'm putting it in"}},
{"s5_c01_refrigerator_047","any",3,"reg=military|day=1,10|mood=sad|world=vehicle,door,building",{1,"Pickup came up with a whole refrigerator strapped in the bed - brand new, still had the tag on the door",2,"Who hauls a refrigerator out of a quarantine?",3,"Somebody who just made the last payment on it",1,"He cut the straps and left it right there on the shoulder when we turned him - door hanging open"}},
{"s5_c01_first_name_048","any",3,"reg=military|day=1,20|mood=sad",{1,"Lady at the barrier called me by my whole name - Darrell Wayne Combs, she taught me Sunday school",2,"She want through?",1,"She wanted me to look her in the eye when I told her no",3,"And did you look her in the eye?",1,"Yes ma'am, that's all I said to her - yes ma'am"}},
{"s5_c01_wrong_side_mail_049","any",2,"reg=military|day=2,12|hour=9,15|mood=funny|world=vehicle",{1,"Mail carrier pulled up to the barrier in the little white truck - asked could she leave the route's mail with us",2,"She's still running her route?",1,"Said nobody told her to stop, said she'll keep coming till somebody in Washington signs something"}},
{"s5_c02_heater_bottle_001","any",3,"reg=military|day=1,30|mood=warm",{1,"Civilian lady in the processing tent had a baby bottle and nothing to warm it with",2,"So what did you do for her?",1,"Showed her the ration heater, splash of water in the bag, bottle in, wait five minutes",3,"It work?",1,"Baby quit crying, she asked could she keep the heater, I gave her four"}},
{"s5_c02_cocoa_thief_002","any",3,"reg=military|day=3,60|mood=funny",{1,"Who opened this case and pulled out every last packet of cocoa?",2,"Don't look at me, Sergeant",3,"Wasn't me either",1,"Then why does Hollis's canteen cup smell like a candy store?",2,"Hollis is a lot of things, Sergeant - Innocent's not one of them"}},
{"s5_c02_pack_date_003","any",2,"reg=military|mood=funny",{1,"Look at the date stamped on this pouch - nineteen eighty-seven",2,"Pork and rice, six years old",1,"My little brother's six",2,"Pork's holding up better - eat it"}},
{"s5_c02_tp_market_004","any",3,"reg=military|day=5,60|mood=funny",{1,"Toilet paper out of the accessory packs is going for two Tootsie Rolls a sheet over in second platoon",2,"That's robbery",3,"That's economics, the whole company's been on the bean menus for a week",1,"I'm buying futures"}},
{"s5_c02_dairy_shake_005","any",2,"reg=military|day=4,40|mood=warm",{1,"I remember a boy with the chaplain, shaking a dairy pouch like a maraca",2,"Did he ever tell anybody his name?",1,"Not while I was there. But he said thank you every time. Somebody raised him right",2,"Somebody sure did"}},
{"s5_c02_astronaut_food_006","any",2,"reg=military|day=1,30|mood=funny",{1,"Kid across the barrier asked me if soldiers eat astronaut food",2,"What's the answer to that?",1,"Told him yes, now he salutes me every morning, I'm not about to correct it"}},
{"s5_c02_wedding_diet_007","any",2,"reg=military|day=3,40|mood=funny",{1,"Twelve hundred calories a bag, it says on the side",2,"You're counting calories? Now?",1,"I was dieting before all this, lost eleven pounds for my cousin's wedding",2,"When's the wedding?",1,"Was the seventeenth, so I'm eating the brownie"}},
{"s5_c02_natural_flavorings_008","any",1,"reg=military|tmp=seasoned,veteran|mood=funny",{1,"Ingredients, water, beef, modified food starch, salt, natural flavorings",1,"Natural flavorings, some man at a desk had to sign off on calling it that",1,"Bet they gave him a medal"}},
{"s5_c02_ice_sheets_009","any",3,"reg=military|day=0,30|hour=11,19|mood=fear|world=cold",{1,"Bring the sheets! Soak 'em in the ice chest and wrap him head to toe",2,"Ice chest's half water, Sergeant",1,"Then it's cold water - wrap him, somebody hold his head up off the dirt",3,"He's shivering now",1,"Good, shivering means he's still in there - keep talking to him, say his name"}},
{"s5_c02_dry_arms_010","any",2,"reg=military|hour=11,18|mood=fear",{1,"Look at Petrie, look at his arms",2,"What about 'em?",1,"Bone dry, it's ninety-eight degrees and he's dry as a paper sack",2,"Get his helmet off and go get Doc, walk, don't run - running makes the whole line jumpy"}},
{"s5_c02_first_hour_011","any",3,"reg=military|day=0,20|mood=grim",{1,"Hot skin, confused, throwing up - Doc, is that the heat or is that the other thing?",2,"For the first hour they look exactly the same",3,"So what do we do for the first hour?",2,"Cool him down, check every inch of skin for a break, and flex-cuff one wrist to the cot",3,"He'll hate that",2,"If it's heat, he'll be alive to hate it"}},
{"s5_c02_salt_tablets_012","any",2,"reg=military|hour=9,18|mood=funny",{1,"Mabry's passing out salt tablets like it's Vietnam",2,"Doc banned those",1,"Mabry says Doc's never seen a real hot day in his life",2,"Doc's from Yuma, Arizona",1,"I'm not the one telling Mabry that"}},
{"s5_c02_hydrant_013","any",3,"reg=military|day=2,25|hour=12,18|mood=warm",{1,"Engineers cracked the fire hydrant on Main with a pipe wrench",2,"That's city water",3,"City's not sending out bills this month",1,"Whole platoon ran through it in their boots - Sergeant too - Sergeant went through twice"}},
{"s5_c02_grape_mix_014","any",2,"reg=military|hour=8,19|mood=funny",{1,"Who dumped a whole can of grape drink mix in the water buffalo?",2,"Nobody was drinking, Sergeant, now everybody's drinking",1,"The whole line's got purple mouths",2,"The whole line's pissing clear, I call that a win"}},
{"s5_c02_turret_ring_015","any",2,"reg=military|tmp=seasoned,veteran|hour=11,18|mood=calm",{1,"Can't keep a gunner up in the turret more than forty minutes - the ring gets too hot to lean on",2,"Rotate every half hour, then",1,"Rotated Scruggs out at noon, he left a patch of elbow on the hatch",2,"Every twenty minutes, then, and somebody find him a towel to put down"}},
{"s5_c02_rash_mutter_016","any",1,"reg=military|hour=10,20|mood=funny",{1,"Rash under the vest, under the belt too",1,"Rash behind both knees, where I didn't know a person could even sweat",1,"If the dead get me, at least they're getting a real itchy meal"}},
{"s5_c02_six_bags_017","any",2,"reg=military|tmp=seasoned,veteran|day=8,60|mood=grim",{1,"How many bags of Ringer's left?",2,"Six",1,"Put the word out - six, not sixty, six",2,"And that helps how?",1,"Men find shade on their own real quick when they know the number"}},
{"s5_c02_twenty_four_018","any",2,"reg=military|role=soldier_green,soldier_nco|day=0,20|mood=fear",{1,"Drill Sergeant, I qualified two weeks ago, twenty-four out of forty",2,"Twenty-three is a pass",1,"So I'm one over",2,"One over is a soldier, and nothing out there pops up for three seconds - they walk straight at you - slow"}},
{"s5_c02_no_yelling_019","any",3,"reg=military|role=soldier_green|day=2,30|hour=4,11|mood=fear",{1,"Drill Sergeant Pettaway hasn't yelled once since Friday",2,"Not once?",3,"He called me by my first name this morning, asked had I slept",1,"That's the scariest thing that's happened on this whole post"}},
{"s5_c02_latrine_buddy_020","any",2,"reg=military|role=soldier_green,soldier_nco|hour=19,5|mood=funny|world=door",{1,"Where's your battle buddy, Private?",2,"Latrine, Drill Sergeant",1,"And what's the rule?",2,"Nobody goes anywhere alone, not even the latrine",1,"Then go stand outside that door and hum, so he knows you're out there",2,"Hum what?",1,"Anything that isn't the Army song, he's heard enough of that"}},
{"s5_c02_holler_021","any",3,"reg=military|role=soldier_green|day=3,60|mood=funny",{1,"Nguyen can't understand one word Tolliver says",2,"I understand him fine, he says holler and he means valley",3,"I say holler 'cause it's a holler",1,"And now Nguyen says y'all, three weeks in Kentucky",2,"It's a useful word, it saves time in a firefight"}},
{"s5_c02_cardboard_ribbon_022","any",3,"reg=military|role=soldier_green,soldier_nco|day=2,60|mood=funny",{1,"Drill Sergeant, does this count as a deployment? For a ribbon?",2,"You want a ribbon",1,"My dad's got a whole row from Panama, I'd just like the one",2,"Private, you finish this with all ten fingers and I'll cut you a ribbon out of an MRE box myself",3,"Can I get one too?",2,"Everybody still standing at the end gets a cardboard ribbon"}},
{"s5_c02_shoppette_man_023","any",2,"reg=military|day=2,30|hour=4,11|mood=grim",{1,"Tolliver froze up when one came to the wire this morning",2,"Everybody freezes on the first one",1,"It was the old man from the shoppette, still had his name badge on - Tolliver bought sunflower seeds off him every Sunday"}},
{"s5_c02_dozer_hydraulics_024","any",2,"reg=military|day=3,60|mood=funny",{1,"Why's Specialist Bohannon talking to the dozer?",2,"Says she's got a hydraulic leak and she likes hearing it's gonna be okay",1,"Does he tell her?",2,"Every hour on the hour, nicer than he's ever talked to any of us"}},
{"s5_c02_school_buses_025","any",3,"reg=military|day=2,30|mood=sad|world=vehicle,building,road",{1,"Engineers pulled every school bus out of the county lot and parked 'em nose to tail across the Riverside road",2,"A wall of yellow",3,"With the school district painted down the side, bus numbers and all",1,"Little boy came up yesterday and showed his mama which one was his"}},
{"s5_c02_storm_grates_026","any",2,"reg=military|tmp=seasoned,veteran|day=3,60|mood=calm",{1,"Weld every storm grate on this side of the line shut",2,"Those things don't crawl drain pipes",1,"Ruiz watched one come out of a culvert Tuesday on its belly - welding's cheaper than finding out how many"}},
{"s5_c02_peach_trees_027","any",3,"reg=military|day=3,40|hour=8,19|mood=sad|world=trees",{1,"Engineers are chainsawing the tree line back two hundred meters - fields of fire",2,"That's somebody's orchard",3,"Peach trees, lady who owns it stood on her porch and watched the whole morning",1,"She say anything?",3,"Asked could she pick the rest before they got to 'em - she's been picking since noon, filled a bathtub"}},
{"s5_c02_sandbag_names_028","any",2,"reg=military|hour=9,20|mood=funny",{1,"Filled five hundred sandbags since breakfast",2,"You counted?",1,"Started naming 'em after old girlfriends to keep myself going",2,"How far'd that get you?",1,"Bag three, then I switched to cousins"}},
{"s5_c02_blasting_machine_029","any",3,"reg=military|day=3,40|mood=fear",{1,"Engineers wired the Salt River bridge last night, just in case",2,"In case of what?",1,"In case the line has to move, nobody's saying which direction",3,"Who's got the blasting machine?",1,"An engineer captain, he sleeps with it on his chest like a teddy bear"}},
{"s5_c02_sleeping_pills_030","any",3,"reg=military|day=5,60|mood=grim|world=vehicle",{1,"MPs picked up two of ours in the drugstore in Muldraugh - pockets full of pills",2,"Selling 'em?",1,"Sleeping pills, for the guys on nights who can't anymore",3,"What happens to them?",1,"Nobody knows where to lock up a soldier right now - they're in the back of the MP truck - asleep, actually"}},
{"s5_c02_traffic_whistle_031","any",2,"reg=military|day=3,60|mood=funny",{1,"Corporal Linville still wears the MP traffic whistle, there's no traffic",2,"Them things turn their heads at it",1,"He figured that out, now he blows it at the far end of the lot and walks back real quick",2,"And he still calls it traffic control"}},
{"s5_c02_holding_cots_032","any",3,"reg=military|day=1,20|mood=grim",{1,"Holding area's got forty civilians who got caught inside the line after curfew",2,"What happens to 'em?",3,"Sleeves up, temperature, twenty-four hours on a cot where we can see 'em",1,"And after the twenty-four?",3,"After the twenty-four we bleach the cots and fill 'em again"}},
{"s5_c02_softball_trophy_033","any",2,"reg=military|day=2,30|mood=sad",{1,"Deputy on the other side of the barrier used to play softball against our MP company - county league",2,"He any good?",1,"Terrible, couldn't hit a slow pitch with a canoe paddle",2,"What'd he want?",1,"Wanted to know did we still have the league trophy - said keep it safe, then he drove off"}},
{"s5_c02_loan_folder_034","any",2,"reg=military|day=3,40|mood=sad",{1,"Monday morning I was supposed to be at my desk at the bank - I'm a loan officer",2,"Anybody coming in?",1,"Young couple, closing on their first house, I had the folder all ready on my desk",2,"They'll understand",1,"They're from Muldraugh"}},
{"s5_c02_chip_route_035","any",2,"reg=military|day=5,60|mood=funny",{1,"Federal law says my boss has to hold my job while I'm activated",2,"What's the job?",1,"Snack delivery route - potato chips, most of it's right here in this county",2,"Well, route's still here",1,"Route's here, stores are here, it's the customers I'm worried about"}},
{"s5_c02_steel_pot_036","any",2,"reg=military|day=1,60|mood=funny|world=building",{1,"Active duty got the new Kevlar, we got steel pots out of the armory basement in Frankfort",2,"Steel pots went out ten years ago",1,"This one's got a name scratched inside - Eddie Lyle, 1971",2,"Then Eddie's pot has been through worse - let it do its job"}},
{"s5_c02_sun_winning_037","any",1,"reg=military|role=soldier_nco|tmp=seasoned,veteran|hour=16,22|mood=grim",{1,"Seven heat casualties since breakfast - no contact - no bites",1,"Kentucky is doing more damage to this company than the dead are",1,"Put that in the report, see does anybody laugh"}},
{"s5_c02_pancakes_log_038","any",1,"reg=military|role=soldier_green|hour=1,5|mood=funny",{1,"Fireguard log, 0300 - bay secure - Beasley talking in his sleep about pancakes",1,"0315 - Beasley still on pancakes, syrup has entered the conversation",1,"0330 - Beasley wants bacon, honestly, Beasley, me too"}},
{"s5_c02_mess_hall_fans_039","any",3,"reg=military|day=0,4|hour=11,16|mood=calm",{1,"Mess hall still had hot chow on Saturday - real trays, big fans going",2,"What was it?",1,"Salisbury steak and those carrots nobody eats",3,"I'd eat the carrots now",2,"I'd eat the carrots and write the cook a thank-you note"}},
{"s5_c02_ration_heater_ban_040","any",2,"reg=military|tmp=seasoned,veteran|hour=20,5|mood=calm",{1,"No heaters after dark on the wire - eat it cold",2,"Heater doesn't make any light",1,"Makes steam, makes a hiss - makes a smell - pick which one you want to explain to the ditch"}},
{"s5_c02_cot_doc_041","any",3,"reg=military|day=3,60|hour=12,19|mood=sad",{1,"Doc's been sitting with that heat case three hours, the kid from Bowling Green",2,"He gonna make it?",3,"He's drinking, he's making jokes about the IV, that's a good sign",1,"Then why's Doc still sitting there?",3,"Because Doc lost one on Wednesday that was drinking and joking too"}},
{"s5_c02_crackers_morse_042","any",2,"reg=military|mood=funny",{1,"These crackers are so dry I could send Morse code tapping 'em on my helmet",2,"What would you send?",1,"Send water - stop, send more cheese spread - stop, send me home"}},
{"s5_c02_barracks_fan_043","any",3,"reg=military|role=soldier_green,soldier|day=5,60|hour=21,4|mood=sad",{1,"You know what I keep hearing when I try to sleep? The barracks box fan",2,"That old thing rattled",1,"It rattled on every third turn, I used to hate it",3,"Power's been off on post since Tuesday",1,"I know, I still hear it rattle - every third turn"}},
{"s5_c02_extra_canteen_044","any",2,"reg=military|day=3,60|hour=10,19|mood=warm",{1,"Somebody clipped a full canteen to my web belt while I was asleep in the Humvee",2,"Who put it there?",1,"Don't know, nobody's owning up, it's got the cold water from the ice chest in it",2,"Then drink it and quit asking, whoever did it wants you to drink it"}},
{"s5_c02_guard_armory_ammo_045","any",3,"reg=military|tmp=seasoned,veteran|day=4,60|mood=grim",{1,"Ammo point wants a signature for every box now, name, unit, and what it's for",2,"What it's for? What do they think it's for?",3,"They want it written down, is all, somebody up there wants a paper trail",1,"I wrote perimeter security",2,"I wrote the same, it's easier to spell"}},
{"s5_c03_rifles_or_not_001","any",3,"reg=military|role=deserter|day=4,120|mood=angry|world=water",{1,"We leave the rifles - walk out looking like civilians and nobody asks us anything",2,"Leave the rifles? With what's walking around out there?",3,"A rifle's what gets you shot at the next checkpoint - they see a rifle, they see a deserter",2,"They see no rifle, they see lunch",1,"Fine, the rifles come - but the uniforms go in the creek"}},
{"s5_c03_nine_men_002","any",2,"reg=military|role=deserter|day=5,120|mood=grim",{1,"Quit calling it deserting - Charlie Company was nine men and a radio that didn't talk back",2,"Nine men and Staff Sergeant Tackett telling us to hold",1,"Tackett told us hold, and then Tackett got bit - who were we holding for?",2,"I don't know - somebody, I just know what the word is for what we did"}},
{"s5_c03_size_six_003","any",3,"reg=military|role=deserter|day=4,120|hour=6,19|mood=funny",{1,"Clothesline behind that farmhouse, jeans, work shirts, the works",2,"That's stealing",3,"You walked off a federal quarantine line with a government rifle - take the jeans",2,"They're a size six",3,"Suck in"}},
{"s5_c03_name_tape_004","any",2,"reg=military|role=deserter|day=4,120|mood=sad|world=building",{1,"Cut your name tape off before we burn the blouses",2,"My mom sewed this name tape on, not the tailor shop - my mom, at the kitchen table",1,"Then keep it in your boot, just don't wear it",2,"Okay, in my boot"}},
{"s5_c03_knobs_or_river_005","any",3,"reg=military|role=deserter|day=4,120|mood=angry|world=water",{1,"River's four miles, we find a boat, we're in Indiana by morning",2,"Every boat on that river gets a searchlight and a warning shot - then it gets no warning",3,"So we go south through the knobs, nobody's watching the knobs",2,"Because nobody's dumb enough to walk the knobs in July",1,"You got a better way? Say it - say it now, or quit shooting mine down"}},
{"s5_c03_going_back_006","any",2,"reg=military|role=deserter|day=4,120|hour=4,8|mood=fear",{1,"I'm going back",2,"They'll shoot you walking up",1,"Not if I come up in daylight, hands on my head, hollering my name and unit",2,"That's what the civilians did",1,"I know what the civilians did, I was standing there"}},
{"s5_c03_hollis_arm_007","any",3,"reg=military|role=deserter|day=4,120|mood=fear",{1,"Why are you holding your arm like that?",2,"Slept on it wrong",3,"Roll up the sleeve",2,"It's a scratch off the concertina, two days ago - I'm fine",1,"Two days isn't enough to be fine or not fine",3,"Roll it up - please"}},
{"s5_c03_guy_with_map_008","any",3,"reg=military|role=deserter|day=4,120|mood=funny",{1,"Why is Wills still giving orders? He walked off same as the rest of us",2,"Because he's the only one who can read a map",3,"I can hear you, I'm no sergeant anymore, just a guy with a map",1,"Alright, guy with a map - where are we?",3,"Lost, but I'm lost in the right direction"}},
{"s5_c03_dog_tags_009","any",2,"reg=military|role=deserter|day=4,120|mood=grim",{1,"You still wearing your dog tags?",2,"Every day",1,"What for? You're not in the Army anymore",2,"If I turn, whoever does it ought to know what name to write down"}},
{"s5_c03_expensive_shade_010","any",3,"reg=military|role=deserter|day=4,120|hour=11,18|mood=funny|world=vehicle",{1,"We should've taken the Humvee",2,"A Humvee with Army bumper numbers rolling down 31W - real sneaky",1,"Beats walking in this heat",3,"It needs diesel and there isn't any, we'd be sitting in the most expensive shade in Kentucky"}},
{"s5_c03_left_work_early_011","any",2,"reg=military|role=deserter|day=4,120|mood=funny",{1,"What's the punishment for desertion? You sat through that class",2,"In wartime it can be death",1,"Is this wartime?",2,"Nobody declared a war, so technically we just left work early"}},
{"s5_c03_strung_it_012","any",2,"reg=military|role=deserter|day=4,120|mood=sad",{1,"My mom's in Radcliff - that's outside, twenty minutes, driving",2,"Twenty minutes through the wire",1,"I know where the wire is, I strung it",2,"Then you know there's no hole in it"}},
{"s5_c03_why_i_left_013","any",2,"reg=military|role=deserter|day=5,120|hour=20,4|mood=grim",{1,"You don't have to say why you left",2,"I fired on the gate that night, I'm not asking anybody to forgive that part",1,"I hear you",2,"I left because they said we'd do it again the next night - and I knew I would"}},
{"s5_c03_supper_offer_014","any",3,"reg=military|role=deserter|day=6,120|mood=calm|world=vehicle",{1,"Militia up at Irvington's taking in soldiers, heard it on the CB in that pickup",2,"Taking in? Or taking our rifles and our boots?",3,"Either way, they feed you",2,"Either way, they know you ran",1,"Everybody in Kentucky knows we ran, only the militia's offering supper"}},
{"s5_c03_scratched_cap_015","any",2,"reg=military|role=deserter|day=4,120|mood=angry",{1,"That's my canteen",2,"It's got my initials scratched in the cap",1,"You scratched them in last night, I watched you do it with your knife",2,"Then it's been mine since last night"}},
{"s5_c03_walking_home_016","any",1,"reg=military|role=deserter|tmp=fresh|day=4,60|hour=20,5|mood=fear",{1,"Private First Class Terrence Mills, absent without leave - day four",1,"Day five, maybe, quit being sure after the barn",1,"Mama, if anybody asks, I was just walking home, that's all I was doing - walking home"}},
{"s5_c03_bird_low_017","any",3,"reg=military|role=deserter|day=4,120|hour=7,19|mood=fear|world=trees",{1,"Down! Under the trees, helicopter coming in low",2,"Is it looking for us?",3,"Nobody's burning fuel to look for four privates",2,"Then why are we under the trees?",3,"Because I've been wrong before"}},
{"s5_c03_smokes_bet_018","any",2,"reg=military|role=deserter|day=5,120|mood=grim",{1,"Pack of smokes says that line isn't standing a month from now",2,"The line, or the soldiers on it?",1,"Does it matter for the bet?",2,"Matters for the smokes, somebody's got to still be around to pay up"}},
{"s5_c03_tomatoes_019","any",3,"reg=military|role=deserter|day=6,120|hour=16,5|mood=angry|world=road",{1,"Farmhouse up the road has a garden and a family - we have rifles, they have tomatoes",2,"We are not doing that to a family",1,"We ask nice with rifles on our shoulders, that's still asking",3,"It isn't asking if they can't say no - we trade, two MREs for a sack of tomatoes",1,"Two whole MREs? For tomatoes?",3,"For getting to go to sleep tonight still being soldiers about it"}},
{"s5_c03_mp_armband_020","any",2,"reg=military|role=deserter|day=5,120|mood=fear",{1,"You think the MPs are out hunting for us?",2,"MPs are hunting for their next hot meal, same as us",1,"Still, every time I see somebody with something on his arm I think MP brassard",2,"Out here, something tied around an arm means a bite - I'd be more scared of that"}},
{"s5_c03_ranger_talk_021","any",3,"reg=military|role=deserter|day=5,120|hour=19,23|mood=funny",{1,"Gilley says he's Ranger qualified, that's how come he knows which berries are okay",2,"Gilley was a supply clerk",3,"I was Ranger qualified in spirit",1,"Are these berries okay, Ranger?",3,"Give 'em to Wills first"}},
{"s5_c03_last_formation_022","any",2,"reg=military|role=deserter|day=6,120|hour=5,8|mood=sad",{1,"Six o'clock, we'd be in formation right now",2,"Nobody's calling a formation",1,"I know, I stood up anyway - just for a second, my feet did it by themselves"}},
{"s5_c03_vfw_muster_023","any",3,"reg=civilian|role=militia|day=1,10|mood=calm",{1,"Forty-one showed up at the VFW hall last night, deer rifles, bird guns, one fella with a black powder muzzleloader",2,"Who's in charge?",3,"Earl Tipton, retired first sergeant, twenty-two years over at Knox",1,"Earl's big on one thing, nobody points a gun at the Army line, three times he told us",2,"And rule two?",1,"Bring your own water"}},
{"s5_c03_hay_wagon_024","any",2,"reg=civilian|role=militia|day=2,60|mood=funny|world=vehicle,road",{1,"Pulled Delbert's hay wagon across the Rock Haven road, bales stacked two high",2,"It stop a truck?",1,"No, stops the dead just fine, though, they get their feet all wound up in the twine",2,"Delbert want his wagon back?",1,"Delbert wants his hay back, his cows don't care one bit about roadblocks"}},
{"s5_c03_blaze_orange_025","any",3,"reg=civilian|role=militia|mood=funny",{1,"Why's everybody wearing blaze orange? Nobody's hunting deer",2,"So we don't shoot each other",3,"So the dead can see us coming a mile off, too",2,"Well, they were coming anyhow"}},
{"s5_c03_buttermilk_026","any",2,"reg=civilian|role=militia|day=2,40|mood=warm",{1,"Carried a pan of cornbread up to the Army barrier - set it on my hood, my side of the paint",2,"They take it?",1,"Can't cross to get it - one of the boys hollered over, what kind is it?",2,"What'd you holler back?",1,"Buttermilk, whole line of 'em groaned like I'd shot 'em"}},
{"s5_c03_keeping_it_on_ours_027","any",2,"reg=civilian|role=militia|tmp=seasoned|day=2,90|mood=angry|world=fence",{1,"Federal government builds a fence around our county, and we're supposed to say thank you",2,"They're keeping it off everybody else's kids, Roy",1,"By keeping it on ours",2,"Yeah... our side only"}},
{"s5_c03_kenny_crossroads_028","any",3,"reg=civilian|role=militia|day=3,90|hour=4,11|mood=grim",{1,"Kenny shot a man at the crossroads this morning, said he was stumbling",2,"Was he one of them?",3,"He was drunk, bottle in his coat pocket - Kenny says drunk walks the same",1,"Earl took Kenny's rifle off him",2,"Kenny's got three more at the house"}},
{"s5_c03_eleven_miles_029","any",3,"reg=civilian|role=militia|day=2,30|mood=sad|world=water,road",{1,"Carload of folks from Valley Station came down the river road - we turned 'em around at the church",2,"Army would've done the same",3,"I'm not the Army, I'm a man doing the Army's job on people I buy feed alongside",1,"You don't buy feed with anybody from Valley Station",3,"Valley Station's eleven miles from my porch"}},
{"s5_c03_coon_hounds_030","any",2,"reg=civilian|role=militia|day=2,90|mood=funny|world=vehicle",{1,"Lonnie's coon hounds won't run the dead",2,"Won't track 'em?",1,"Track 'em fine - get close, bay one time, then turn around and go sit in the truck",2,"Smartest members of this whole outfit"}},
{"s5_c03_back_in_ten_031","any",2,"reg=civilian|role=militia|day=3,90|mood=funny|world=door,road",{1,"I remember a radio call about the Ekron store. Somebody saying the road was clear",2,"Clear when they looked. Didn't tell us what we'd find there",1,"Sign said Back In Ten Minutes. Longest ten minutes I'd ever seen",2,"A sign's easier to leave behind than a shop. I hope they got home"}},
{"s5_c03_satterly_boy_032","any",3,"reg=civilian|role=militia|day=3,90|mood=warm",{1,"Who let the Satterly boy come on patrol? He's fifteen",2,"His daddy's gone, he's carrying his daddy's rifle",1,"It's a single-shot twenty-two",3,"It's his daddy's single-shot twenty-two",1,"Fine, he walks behind me - right behind me, where I can hear him breathe"}},
{"s5_c03_methodists_033","any",2,"reg=civilian|role=militia|day=5,60|mood=funny",{1,"Harold raised a ham operator down in Tennessee last night",2,"What are they saying out there?",1,"Fella said the TV calls us contained, then he asked Harold was it true we'd gone to eating each other",2,"What'd Harold say?",1,"Said no sir, we're Methodists, then the signal quit"}},
{"s5_c03_coffee_can_star_034","any",3,"reg=civilian|role=militia|day=2,40|mood=funny",{1,"Sheriff swore every one of us in on the courthouse steps - right hands up",2,"Does it pay?",3,"Pays exactly what it paid before he said the words",1,"I got a badge, though, star cut out of a coffee can lid",2,"Real shiny"}},
{"s5_c03_posthole_digger_035","any",2,"reg=civilian|role=militia|day=3,90|mood=grim|world=building",{1,"That one by the mailbox - blue suit, that's Wade Hensley",2,"That was Wade Hensley",1,"He still owes me a posthole digger",2,"I'll do this, you go on and get your digger out of his shed"}},
{"s5_c03_four_inches_left_036","any",3,"reg=civilian|role=militia|tmp=seasoned|day=3,120|mood=calm",{1,"Nobody's sighting in rifles anymore, every shot costs a round and calls 'em in",2,"My scope got knocked Tuesday, it's shooting four inches left",3,"Then hold four inches right and quit asking for bullets",2,"At fifty yards?",3,"Don't shoot at fifty yards, let 'em come to twenty-five - they're patient - be patienter"}},
{"s5_c03_thirty_thirty_037","any",2,"reg=civilian|role=militia|day=4,120|hour=4,11|mood=sad",{1,"Doreen Cundiff outshot every man at the gravel pit this morning",2,"Shooting what?",1,"Her husband's thirty-thirty, said he never did keep it clean",2,"Where's her husband?",1,"She didn't say, she cleans it every night"}},
{"s5_c03_leaflet_burn_038","any",3,"reg=civilian|role=militia|day=4,40|mood=angry",{1,"Plane dropped leaflets, says civilians in the quarantine gotta hand over all firearms at the checkpoints",2,"Walk up to that line carrying a rifle? Get shot handing it over, more like",3,"Maybe that's the idea",1,"Earl says they'll do fine for starting the burn barrel - said it with a straight face"}},
{"s5_c03_feed_store_prayer_039","any",1,"reg=civilian|role=militia|tmp=fresh|hour=21,5|mood=fear",{1,"Lord, I used to manage a feed store. Never expected to spend so long thinking about a rifle",1,"If I ever need one, let there be somebody who can teach me without laughing",1,"Earl was in the Army. I wish I'd asked him more when I had the chance"}},
{"s5_c03_ridge_binoculars_040","any",3,"reg=civilian|role=militia|day=4,90|mood=grim",{1,"I watched the gate that night from up on the ridge - through binoculars",2,"You never told me that",1,"I ain't telling it now, I'm just saying I was there",3,"That's enough, Dale",1,"It's enough"}},
{"s5_c03_bleeding_feet_041","any",3,"reg=civilian|role=militia|day=5,90|mood=warm",{1,"Soldier boy walked into the Pentecostal church yard last night - no rifle, no boots, feet cut to ribbons",2,"Deserter",3,"Nineteen and bleeding - call him whatever you want after his feet are wrapped",2,"And if the Army comes asking?",3,"Army has my phone number - tell 'em to call"}},
{"s5_c03_green_beans_042","any",2,"reg=civilian|role=militia|day=6,120|mood=funny|world=building",{1,"Church pantry's got sixty-one cans of green beans and four cans of anything else",2,"Who gave sixty-one cans of green beans?",1,"Every family in the county cleaned out the back of the cupboard for the food drive in March",2,"So we're living on what nobody wanted",1,"And thanking the Lord for it before every meal"}},
{"s5_c03_steeple_bats_043","any",2,"reg=civilian|role=militia|hour=17,22|mood=funny",{1,"Your turn up in the church steeple tonight",2,"I did the steeple Tuesday - bats",1,"Bats are on our side",2,"Bats don't know that, they made that real clear to me"}},
{"s5_c03_my_boys_age_044","any",2,"reg=civilian|role=militia|day=2,60|mood=sad",{1,"I remember the soldiers at the line looking too young to shave",2,"He's my boy's age",1,"Last you'd heard, your boy was in Germany",2,"I know what I'd heard. I kept seeing his age in their faces"}},
{"s5_c03_say_names_slow_045","any",3,"reg=civilian|role=militia|day=4,120|mood=sad",{1,"Who's saying the words over the Lanham girls?",2,"Brother Cecil's gone to his sister's in Rosewood",3,"I'll do it, I don't know the verses, though",1,"Nobody out here knows the verses anymore, just say their names slow"}},
{"s5_c03_twelve_at_ekron_046","any",3,"reg=civilian|role=militia|tmp=predator,seasoned|day=5,90|hour=16,5|mood=angry",{1,"There's forty of us, twelve of them at that Ekron checkpoint, I counted twice",2,"And behind those twelve is the whole United States Army",1,"The whole Army's not sitting at Ekron - twelve are",3,"Earl's not marching forty farmers into a machine gun, Kenny - sit down",1,"Earl's not the boss of me",3,"He is tonight"}},
{"s5_c03_no_bag_limit_047","any",3,"reg=civilian|role=militia|day=3,120|mood=funny",{1,"Say what you want, there's no bag limit on the dead",2,"No season, either",3,"Game warden would still find a way to write you a ticket for it"}},
{"s5_c03_bridge_watch_048","any",2,"reg=civilian|role=militia|day=3,90|hour=0,5|mood=fear",{1,"Something's on the low-water bridge - hear it splashing?",2,"Just a deer",1,"Deer don't stop halfway and stand there",2,"Then don't shine the light - let it come, we'll know it by the walk"}},
{"s5_c03_army_surplus_049","any",3,"reg=civilian|role=militia|day=2,60|mood=funny",{1,"Dwayne bought a whole Army surplus outfit at the flea market in Elizabethtown - pants, jacket, the hat",2,"How'd that go over?",3,"And the Army checkpoint won't quit waving at him through their binoculars - thinks he's one of theirs",1,"He waves back - Proudest I've ever seen that man"}},
{"s5_c03_turned_back_mother_050","any",2,"reg=civilian|role=militia|tmp=fresh,seasoned|day=3,40|mood=sad|world=water",{1,"Woman who pulled up to our roadblock used to babysit me - asked did I really mean to tell her no",2,"Mrs. Bewley?",1,"Mrs. Bewley, she fed me grilled cheese every Tuesday for three years",2,"What'd she want?",1,"To get to her sister's across the creek, I turned her around, she told me I'd grown up real nice"}},
{"s5_c03_minutes_book_051","any",1,"reg=civilian|role=militia|tmp=seasoned|day=5,120|hour=19,23|mood=grim",{1,"Minutes of the county defense meeting - present, thirty-three - absent, eight",1,"Cross out absent - Earl says write deceased where we know it",1,"We know it for six, leaving two as absent, they might just be late"}},
{"s5_camp_charms_trade_001","any",3,"reg=military|mood=funny",{1,"Remember trying to trade away the omelet with ham?",2,"Nobody on God's green earth wants the omelet with ham",3,"I once offered my Charms with it",1,"Charms are bad luck and you know it",3,"And that's how I ended up keeping the omelet"}},
{"s5_camp_ohio_rucksack_002","any",3,"reg=military|day=2,29|mood=sad|world=cars",{1,"Ohio's been sitting on his rucksack with his boots laced up for an hour",2,"Waiting on what?",1,"Says buses are coming to take the trainees home, somebody told him",3,"Who'd tell him a thing like that?",1,"Nobody, he told himself"}},
{"s5_camp_ohio_fields_003","any",2,"reg=military|role=soldier_green,soldier_nco|day=2,29|mood=fear|world=road",{1,"Sergeant, Chillicothe's only four hours up the road, I could be home for supper",2,"The road's closed, Private",1,"I'd go around the road, through the fields, I'm real good at fields",2,"You're good at fields - sit down, drink this, and tell me about the fields"}},
{"s5_camp_black_flag_004","any",2,"reg=military|tmp=seasoned,veteran|hour=11,17|mood=grim",{1,"Flag's black, heat category five",2,"Black flag means no training",1,"Used to mean no training, now it means a canteen an hour and stay on the wire"}},
{"s5_camp_shade_tent_005","any",3,"reg=military|day=0,14|hour=12,18|mood=fear",{1,"Doc's got four IVs running in the shade tent",2,"Heat? Or the other thing?",3,"Heat, I checked every one of 'em myself - no bites, no scratches - just cooked",1,"Put them on the cots by the fan, and somebody watch them anyway"}},
{"s5_camp_radio_check_006","any",2,"reg=military|hour=6,10|mood=calm",{1,"{callsign}, this is Kilo-Two-Six, radio check, over",2,"Nothing, that's three times",1,"{callsign}, Kilo-Two-Six, how copy, over",2,"They're not there, or they're there and they're not talking",1,"Log it, we try again at the top of the hour"}},
{"s5_camp_tabasco_007","any",2,"reg=military|mood=funny|world=building",{1,"You put hot sauce on the peanut butter?",2,"I put it on everything, it's the only thing in the bag that tastes like it came out of a kitchen",1,"That's a sickness",2,"Everybody's got one now - mine's delicious"}},
{"s5_camp_pound_cake_008","any",3,"reg=military|day=5,60|mood=funny",{1,"Anybody got a dry pair of socks? I'll pay a whole pound cake",2,"A whole pound cake?",3,"Don't, he ate that pound cake Tuesday, he's selling you the memory of it",1,"The memory was excellent"}},
{"s5_camp_meatloaf_009","any",2,"reg=military|role=soldier_green|hour=0,4|mood=fear",{1,"You awake?",2,"I'm on fireguard, I'm supposed to be awake",1,"Can you just keep talking? Don't matter about what",2,"My mom puts saltines in her meatloaf instead of bread - that's the family secret",1,"Keep going"}},
{"s5_camp_cant_cook_010","any",3,"reg=military|day=3,60|mood=sad|world=vehicle",{1,"Mail truck hasn't come since before Friday, I'm still writing mine",2,"Who's gonna carry it?",1,"Don't care, the writing's for me",3,"Put in there you miss her cooking, they like that",1,"I do miss her cooking, and she can't cook, that's how you know it's bad"}},
{"s5_camp_white_tent_011","any",3,"reg=military|day=1,15|mood=fear",{1,"Guys in the signal tent say the people in the white suits flew out yesterday",2,"Flew out to where?",1,"Out, that's the only word they used",3,"Then who's in the white tent now?",1,"Nobody's gone in or come out of it since"}},
{"s5_camp_last_battery_012","any",2,"reg=military|tmp=seasoned,veteran|day=5,90|mood=calm",{1,"Last radio battery in the box, after this the set's a paperweight",2,"Pull the one out of the dead Humvee",1,"Already did, this is that one"}},
{"s5_camp_roll_call_013","any",3,"reg=military|day=3,90|hour=5,8|mood=sad",{1,"Morning count, sound off, and don't mumble at me",2,"Here, Sergeant",1,"Garza?",2,"On post two",1,"Wheeler?",3,"Sergeant",1,"I know - I know - habit - moving on"}},
{"s5_camp_coffee_shave_014","any",2,"reg=military|day=3,60|mood=funny",{1,"Why are you shaving? Water's rationed",2,"Sergeant says the end of the world is no excuse to look like a mountain man",1,"Did Sergeant shave?",2,"Sergeant shaved with his coffee"}},
{"s5_camp_cocoa_015","any",3,"reg=military|hour=4,7|mood=warm",{1,"Who made cocoa?",2,"Sergeant, canteen cup on a heat tab for each of us - set 'em on the sandbags and never said a word",3,"Sergeant hates cocoa",2,"Sergeant didn't drink any"}},
{"s5_camp_orange_sky_016","any",2,"reg=military|day=1,20|hour=21,3|mood=fear",{1,"Sky up north is orange again",2,"Louisville",1,"How much of a city has to be on fire before you see it from here?",2,"Don't do that math, watch your sector"}},
{"s5_camp_wildcats_017","any",3,"reg=military|mood=funny",{1,"Basketball season's gonna start without us",2,"There's not gonna be a basketball season, Mullins",1,"Then the Wildcats go undefeated - think about it",3,"He's not wrong - who's gonna beat 'em?"}},
{"s5_camp_rodgers_cold_018","any",3,"reg=military|day=0,20|hour=12,18|mood=fear",{1,"Rodgers is sitting in the shade saying he's cold",2,"Cold? It's ninety-six out",3,"That's heat stroke, blouse off, water on him, feet up",1,"What if it ain't heat?",3,"Then you'll know soon enough - water - now"}},
}
